import{_ as a,o as l,c as d,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"إطار الحوكمة وتوازن السلطات","description":"","frontmatter":{},"headers":[],"relativePath":"ar/49-治理框架与权力制衡.md","filePath":"ar/49-治理框架与权力制衡.md","lastUpdated":1789183869000}'),r={name:"ar/49-治理框架与权力制衡.md"};function e(h,t,o,n,s,b){return l(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="إطار-الحوكمة-وتوازن-السلطات" tabindex="-1">إطار الحوكمة وتوازن السلطات <a class="header-anchor" href="#إطار-الحوكمة-وتوازن-السلطات" aria-label="Permalink to &quot;إطار الحوكمة وتوازن السلطات&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>49</td></tr><tr><td>الوحدة</td><td>النظام القانوني وإطار الحوكمة</td></tr><tr><td>الكلمات المفتاحية</td><td>فصل وتوازن السلطات الثلاث، إطار الحوكمة، المجلس التشريعي للمرساة، اللجنة التنفيذية التكافلية، محكمة التكافل، لجنة الرقابة للمرساة</td></tr></tbody></table><h2 id="أولاً-نظرة-عامة-على-إطار-الحوكمة" tabindex="-1">أولاً: نظرة عامة على إطار الحوكمة <a class="header-anchor" href="#أولاً-نظرة-عامة-على-إطار-الحوكمة" aria-label="Permalink to &quot;أولاً: نظرة عامة على إطار الحوكمة&quot;">​</a></h2><p>يُبنى إطار الحوكمة في حضارة التكافل المرساة على مبدأ «فصل وتوازن السلطات الثلاث»، مشكلاً نظام حوكمة يتوازن فيه المجلس التشريعي للمرساة (السلطة التشريعية) واللجنة التنفيذية التكافلية (السلطة التنفيذية) ومحكمة التكافل (السلطة القضائية) ويتراقبون، بينما تمارس لجنة الرقابة للمرساة سلطة الرقابة عبر العملية بأكملها. يهدف هذا الإطار إلى منع إساءة استعمال السلطة، وضمان أن تخدم الحوكمة تقدم عشرة آلاف عرق معاً، وضمان سيادة القانون والعدالة داخل كون هنغ يوان.</p><p>يتبع إطار الحوكمة المبادئ الأساسية التالية:</p><table tabindex="0"><thead><tr><th>المبدأ</th><th>المضمون</th></tr></thead><tbody><tr><td>فصل وتوازن السلطات الثلاث</td><td>السلطات التشريعية والتنفيذية والقضائية مستقلة وتتراقب؛ ولا يجوز لأي سلطة الهيمنة</td></tr><tr><td>الرقابة الشاملة</td><td>تجري لجنة الرقابة للمرساة رقابة على عملية الحوكمة بأكملها</td></tr><tr><td>الحوكمة بسيادة القانون</td><td>تعمل جميع السلطات ضمن الإطار القانوني؛ ويجب أن تكون تصرفات الحوكمة مشروعة</td></tr><tr><td>المشاركة متعددة الأعراق</td><td>تشارك جميع الأعراق في الحوكمة عبر السبل المناسبة، لضمان أن تمثل الحوكمة إرادة جميع الأعراق</td></tr><tr><td>الانفتاح والشفافية</td><td>أنشطة الحوكمة منفتحة وشفافة، لضمان حق الجمهور في المعرفة والمشاركة</td></tr><tr><td>خدمة المصلحة العامة التكافلية</td><td>توجد الحوكمة لخدمة تقدم عشرة آلاف عرق معاً؛ ويُحظر استخدام السلطة العامة للمصلحة الخاصة</td></tr></tbody></table><h2 id="ثانياً-هيكل-إطار-الحوكمة" tabindex="-1">ثانياً: هيكل إطار الحوكمة <a class="header-anchor" href="#ثانياً-هيكل-إطار-الحوكمة" aria-label="Permalink to &quot;ثانياً: هيكل إطار الحوكمة&quot;">​</a></h2><p>يشمل إطار الحوكمة في حضارة التكافل المرساة الأجهزة التالية:</p><table tabindex="0"><thead><tr><th>الجهاز</th><th>الطبيعة</th><th>الوظائف الأساسية</th></tr></thead><tbody><tr><td>المجلس التشريعي للمرساة</td><td>جهاز تشريعي</td><td>سن القوانين وتعديلها، فحص واعتماد الخطط والميزانيات الكبرى، الإشراف على الجهازين التنفيذي والقضائي</td></tr><tr><td>اللجنة التنفيذية التكافلية</td><td>جهاز تنفيذي</td><td>تنفيذ القوانين، إدارة الشؤون العامة، إدارة الشؤون الاقتصادية والثقافية والاجتماعية والزراعية</td></tr><tr><td>محكمة التكافل</td><td>جهاز قضائي</td><td>ممارسة سلطة الفصل بشكل مستقل، حل النزاعات، حماية سلطة سيادة القانون</td></tr><tr><td>لجنة الرقابة للمرساة</td><td>جهاز رقابي</td><td>الرقابة على جميع أجهزة الحوكمة، التحقيق في الفساد والإهمال في الواجبات</td></tr></tbody></table><p>بالإضافة إلى ذلك، تُنشأ مؤسسات استشارية ولجان خبراء ومجالس ممثلين للأعراق لتقديم الدعم الاستشاري للحوكمة.</p><h2 id="ثالثاً-المجلس-التشريعي-للمرساة-السلطة-التشريعية" tabindex="-1">ثالثاً: المجلس التشريعي للمرساة (السلطة التشريعية) <a class="header-anchor" href="#ثالثاً-المجلس-التشريعي-للمرساة-السلطة-التشريعية" aria-label="Permalink to &quot;ثالثاً: المجلس التشريعي للمرساة (السلطة التشريعية)&quot;">​</a></h2><h3 id="أ-التشكيل-ومدة-الولاية" tabindex="-1">(أ) التشكيل ومدة الولاية <a class="header-anchor" href="#أ-التشكيل-ومدة-الولاية" aria-label="Permalink to &quot;(أ) التشكيل ومدة الولاية&quot;">​</a></h3><p>المجلس التشريعي للمرساة هو أعلى جهاز تشريعي في كون هنغ يوان، ويتكون أعضاؤه من ممثلين منتخبين من جميع الأعراق وجميع الأبعاد. مدة الولاية عشر سنوات معيارية، مع إعادة انتخاب منتظمة.</p><h3 id="ب-السلطة-التشريعية" tabindex="-1">(ب) السلطة التشريعية <a class="header-anchor" href="#ب-السلطة-التشريعية" aria-label="Permalink to &quot;(ب) السلطة التشريعية&quot;">​</a></h3><p>يمارس المجلس التشريعي للمرساة السلطات التشريعية التالية:</p><ol><li>سن وتعديل الدستور التكافلي.</li><li>سن وتعديل القوانين الأساسية (القانون الجنائي والقانون المدني وقانون الزراعة وغيرها).</li><li>سن وتعديل اللوائح الإدارية والقوانين الخاصة.</li><li>تفسير القوانين والإشراف على تنفيذها.</li></ol><h3 id="ج-سلطة-القرار" tabindex="-1">(ج) سلطة القرار <a class="header-anchor" href="#ج-سلطة-القرار" aria-label="Permalink to &quot;(ج) سلطة القرار&quot;">​</a></h3><p>يمارس المجلس التشريعي للمرساة سلطات القرار التالية:</p><ol><li>فحص واعتماد خطة التنمية الحضارية والميزانية السنوية.</li><li>فحص واعتماد مشاريع البناء الكبرى والشؤون الدولية (بين الأكوان) المهمة.</li><li>البت في الحرب والسلام وغيرها من شؤون الدولة الكبرى.</li><li>انتخاب أو تعيين أو إقالة كبار القيادات.</li></ol><h3 id="د-سلطة-الرقابة" tabindex="-1">(د) سلطة الرقابة <a class="header-anchor" href="#د-سلطة-الرقابة" aria-label="Permalink to &quot;(د) سلطة الرقابة&quot;">​</a></h3><p>يشرف المجلس التشريعي للمرساة على الجهازين التنفيذي والقضائي، بما في ذلك:</p><ol><li>الاستماع إلى تقارير العمل والمداولة بشأنها.</li><li>إجراءات الاستجواب والسؤال.</li><li>لجان التحقيق الخاصة.</li><li>التصويت على حجب الثقة عن اللجنة التنفيذية (وفقاً للقانون).</li></ol><h2 id="رابعاً-اللجنة-التنفيذية-التكافلية-السلطة-التنفيذية" tabindex="-1">رابعاً: اللجنة التنفيذية التكافلية (السلطة التنفيذية) <a class="header-anchor" href="#رابعاً-اللجنة-التنفيذية-التكافلية-السلطة-التنفيذية" aria-label="Permalink to &quot;رابعاً: اللجنة التنفيذية التكافلية (السلطة التنفيذية)&quot;">​</a></h2><h3 id="أ-الهيكل-التنظيمي" tabindex="-1">(أ) الهيكل التنظيمي <a class="header-anchor" href="#أ-الهيكل-التنظيمي" aria-label="Permalink to &quot;(أ) الهيكل التنظيمي&quot;">​</a></h3><p>اللجنة التنفيذية التكافلية هي أعلى جهاز تنفيذي في كون هنغ يوان، وتتكون من الرئيس التنفيذي ورؤساء الإدارات. يُنتخب الرئيس التنفيذي من المجلس التشريعي للمرساة ويُعيّن بعد التأكيد.</p><h3 id="ب-الوظائف-الإدارية" tabindex="-1">(ب) الوظائف الإدارية <a class="header-anchor" href="#ب-الوظائف-الإدارية" aria-label="Permalink to &quot;(ب) الوظائف الإدارية&quot;">​</a></h3><p>تمارس اللجنة التنفيذية التكافلية الوظائف التالية:</p><ol><li>تنفيذ قوانين وقرارات المجلس التشريعي للمرساة.</li><li>إدارة الشؤون الاقتصادية والاجتماعية والثقافية والتعليمية والطبية والزراعية.</li><li>وضع اللوائح والسياسات الإدارية.</li><li>إدارة الموارد العامة وصندوق التراكم العام.</li><li>معالجة الشؤون الدبلوماسية مع الأكوان الأخرى.</li></ol><h3 id="ج-قيود-السلطة" tabindex="-1">(ج) قيود السلطة <a class="header-anchor" href="#ج-قيود-السلطة" aria-label="Permalink to &quot;(ج) قيود السلطة&quot;">​</a></h3><p>تخضع سلطة اللجنة التنفيذية التكافلية للقيود التالية:</p><ol><li>يجب رفع القرارات الكبرى إلى المجلس التشريعي للمرساة للمراجعة.</li><li>لا يجوز أن تتعارض اللوائح الإدارية مع القوانين.</li><li>تخضع التصرفات الإدارية للمراجعة القضائية من محكمة التكافل.</li><li>تشرف لجنة الرقابة للمرساة على ممارسة السلطة الإدارية.</li></ol><h2 id="خامساً-محكمة-التكافل-السلطة-القضائية" tabindex="-1">خامساً: محكمة التكافل (السلطة القضائية) <a class="header-anchor" href="#خامساً-محكمة-التكافل-السلطة-القضائية" aria-label="Permalink to &quot;خامساً: محكمة التكافل (السلطة القضائية)&quot;">​</a></h2><p>محكمة التكافل هي أعلى جهاز قضائي في كون هنغ يوان، تمارس سلطة الفصل بشكل مستقل. تشمل وظائفها الأساسية:</p><ol><li>الفصل في القضايا المدنية والجنائية والإدارية والزراعية.</li><li>الفصل في القضايا الدستورية وممارسة المراجعة الدستورية.</li><li>ممارسة سلطة التفسير القانوني الموحد.</li><li>تنفيذ الأحكام وحماية سلطة سيادة القانون.</li></ol><p>استقلال محكمة التكافل مضمون بالدستور والقوانين؛ ويتمتع القضاة بولاية مدى الحياة ولا يجوز استبدالهم تعسفاً أثناء الولاية. تخضع السلطة القضائية لإشراف المجلس التشريعي للمرساة ولجنة الرقابة للمرساة، لكن لا يجوز لأي جهاز التدخل في الفصل المستقل في القضايا الفردية.</p><h2 id="سادساً-لجنة-الرقابة-للمرساة-السلطة-الرقابية" tabindex="-1">سادساً: لجنة الرقابة للمرساة (السلطة الرقابية) <a class="header-anchor" href="#سادساً-لجنة-الرقابة-للمرساة-السلطة-الرقابية" aria-label="Permalink to &quot;سادساً: لجنة الرقابة للمرساة (السلطة الرقابية)&quot;">​</a></h2><h3 id="أ-الإنشاء-ومدة-الولاية" tabindex="-1">(أ) الإنشاء ومدة الولاية <a class="header-anchor" href="#أ-الإنشاء-ومدة-الولاية" aria-label="Permalink to &quot;(أ) الإنشاء ومدة الولاية&quot;">​</a></h3><p>لجنة الرقابة للمرساة هي أعلى جهاز رقابي في كون هنغ يوان، تُنشأ وفقاً للدستور، ولها سلطة الرقابة على جميع أجهزة الحوكمة والموظفين العموميين.</p><h3 id="ب-الوظائف-الرقابية" tabindex="-1">(ب) الوظائف الرقابية <a class="header-anchor" href="#ب-الوظائف-الرقابية" aria-label="Permalink to &quot;(ب) الوظائف الرقابية&quot;">​</a></h3><p>تمارس لجنة الرقابة للمرساة الوظائف التالية:</p><ol><li>الرقابة على مدى التزام جميع أجهزة الحوكمة بالقوانين وتنفيذها.</li><li>التحقيق في الفساد والإهمال في الواجبات وإساءة استعمال السلطة ومعالجتها.</li><li>الرقابة على استخدام الموارد العامة وصندوق التراكم العام.</li><li>تلقي الشكاوى والبلاغات من جميع الكائنات وتسجيلها للتحقيق.</li><li>تقديم تقارير الرقابة إلى المجلس التشريعي للمرساة.</li></ol><h3 id="ج-الضمانات-الإجرائية" tabindex="-1">(ج) الضمانات الإجرائية <a class="header-anchor" href="#ج-الضمانات-الإجرائية" aria-label="Permalink to &quot;(ج) الضمانات الإجرائية&quot;">​</a></h3><p>تخضع رقابة لجنة الرقابة للمرساة لإجراءات صارمة: تتبع التحقيقات الإجراءات القانونية؛ وتُحمى حقوق ومصالح الخاضعين للتحقيق؛ وتكون نتائج الرقابة منفتحة وشفافة.</p><h2 id="سابعاً-التراجع-والتوازن-بين-السلطات" tabindex="-1">سابعاً: التراجع والتوازن بين السلطات <a class="header-anchor" href="#سابعاً-التراجع-والتوازن-بين-السلطات" aria-label="Permalink to &quot;سابعاً: التراجع والتوازن بين السلطات&quot;">​</a></h2><p>يتجلى التراجع والتوازن بين سلطات الحوكمة في:</p><table tabindex="0"><thead><tr><th>السلطة</th><th>تراقبها</th><th>آلية التوازن</th></tr></thead><tbody><tr><td>السلطة التشريعية (المجلس التشريعي للمرساة)</td><td>حق النقض التنفيذي، المراجعة القضائية</td><td>يمكن للتنفيذية إعادة مشاريع القوانين مع الاعتراضات؛ ويمكن للمحكمة مراجعة القوانين</td></tr><tr><td>السلطة التنفيذية (اللجنة التنفيذية)</td><td>المراجعة التشريعية، المراجعة القضائية، الرقابة</td><td>القوانين والميزانيات تراجعها التشريعية؛ التصرفات الإدارية تراجعها المحاكم؛ الرقابة من الجهاز الرقابي</td></tr><tr><td>السلطة القضائية (محكمة التكافل)</td><td>المراجعة التشريعية، الرقابة</td><td>القضاة يعينون ويقيلون من التشريعية؛ الانضباط القضائي تراقبه الجهاز الرقابي</td></tr><tr><td>السلطة الرقابية (لجنة الرقابة)</td><td>المراجعة التشريعية، القيود الإجرائية</td><td>نطاق الرقابة وإجراءاتها محددة قانوناً؛ التشريعية تشرف على عملها</td></tr></tbody></table><h2 id="ثامناً-المشاركة-متعددة-الأعراق-في-الحوكمة" tabindex="-1">ثامناً: المشاركة متعددة الأعراق في الحوكمة <a class="header-anchor" href="#ثامناً-المشاركة-متعددة-الأعراق-في-الحوكمة" aria-label="Permalink to &quot;ثامناً: المشاركة متعددة الأعراق في الحوكمة&quot;">​</a></h2><p>يضمن إطار الحوكمة مشاركة جميع الأعراق عبر السبل التالية:</p><ol><li><strong>مجالس ممثلي الأعراق</strong>: ينشئ كل عرق مجلس ممثلين عرقيين، وينتخب ممثلين للمشاركة في المجلس التشريعي للمرساة.</li><li><strong>التمثيل النسبي</strong>: يضمن توزيع المقاعد في المجلس التشريعي للمرساة تمثيل الأعراق الكبرى والتمثيل الأساسي للأعراق الصغرى.</li><li><strong>آلية النقض العرقي</strong>: بالنسبة للتشريعات المتعلقة بالمصالح الحيوية لعرق معين، يمكن لمجلس ممثلي العرق ممارسة نقض عرقي؛ ويلزم إجراء تصويت خاص لتجاوزه.</li><li><strong>الحوكمة التشاورية</strong>: تُحكم شؤون الأعراق الخاصة عبر التشاور مع الأعراق المعنية.</li></ol><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p><em>إطار الحوكمة وتوازن السلطات</em> هو النواة المؤسسية لحوكمة سيادة القانون في حضارة التكافل المرساة. بإنشاء هيكل حوكمة «فصل وتوازن السلطات الثلاث» ومؤسسة الرقابة الشاملة وآلية المشاركة متعددة الأعراق، يضمن عمل السلطة العامة بشكل قانوني وعادل وشفاف، ويمنع إساءة استعمال السلطة والفساد، ويوفر ضمانات مؤسسية لتقدم عشرة آلاف عرق معاً.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>40-共生宪法总纲 (الدستور التكافلي: المبادئ العامة)</li><li>48-司法体系与裁决机制 (النظام القضائي وآلية الفصل في المنازعات)</li><li>30-锚点议事会职能与议事规则 (وظائف وقواعد عمل المجلس التشريعي للمرساة)</li><li>31-共生执行委员会职能与运行机制 (وظائف وآلية عمل اللجنة التنفيذية التكافلية)</li><li>32-锚点监督委员会职能与监察机制 (وظائف وآلية الرقابة للجنة الرقابة للمرساة)</li></ul>',53)])])}const u=a(r,[["render",e]]);export{p as __pageData,u as default};
